 const auto& d=in.document;const auto& c=in.config;const auto& t=in.theme;if(!measure||d.nodes.empty())throw std::runtime_error("Block requires measured labels");std::vector<Size> sizes(d.nodes.size());std::vector<BlockTextBox> labels(d.nodes.size());const double pad=c.padding,line_height=c.font_size*1.5;
 auto metric=[&](std::u16string_view value){auto m=measure(value,c.font_size);if(!m)throw std::runtime_error(m.error());return *m;};
 for(std::size_t i=1;i<d.nodes.size();++i){const auto& n=d.nodes[i];if(n.type==u"space")continue;labels[i]=metric(n.label);auto& s=sizes[i];const auto w=labels[i].advance,h=n.label.empty()?0:line_height;if(n.type==u"composite"){s.w=w;s.h=h;}else if(n.type==u"diamond"){s.w=s.h=w+h+2*pad;}else if(n.type==u"block_arrow"){s.h=h+2*pad;s.w=w+s.h+pad;}else{s.w=w+4*pad;s.h=h+2*pad;}}
 std::function<void(std::size_t,double,double)> set_sizes=[&](std::size_t i,double sibling_w,double sibling_h){auto& s=sizes[i];const auto& n=d.nodes[i];if(!s.w)s={0,0,sibling_w,sibling_h};if(n.children.empty())return;for(auto child:n.children)set_sizes(child,0,0);double max_w=0,max_h=0;for(auto child:n.children)if(d.nodes[child].type!=u"space"){max_w=std::max(max_w,sizes[child].w/d.nodes[child].span);max_h=std::max(max_h,sizes[child].h);}for(auto child:n.children){const auto span=d.nodes[child].span;sizes[child]={0,0,max_w*span+pad*(span-1),max_h};}for(auto child:n.children)set_sizes(child,max_w,max_h);int items=0;for(auto child:n.children)items+=d.nodes[child].span;auto columns=static_cast<int>(n.children.size());if(n.columns>0&&n.columns<items)columns=n.columns;const auto rows=std::ceil(double(items)/columns);double w=columns*(max_w+pad)+pad,h=rows*(max_h+pad)+pad;if(w<sibling_w){w=sibling_w;h=sibling_h;for(auto child:n.children)sizes[child]={0,0,(sibling_w-columns*pad-pad)/columns,(sibling_h-rows*pad-pad)/rows};}if(w<s.w){w=s.w;const auto count=n.columns>0?std::min(static_cast<int>(n.children.size()),n.columns):static_cast<int>(n.children.size());for(auto child:n.children)sizes[child].w=(w-count*pad-pad)/count;}s={0,0,w,h};};
 set_sizes(0,0,0);
